  1833  static int coolkey_compute_crypt(sc_card_t *card,
  1834                                          const u8 * data, size_t datalen,
  1835                                          u8 * out, size_t outlen)
  1836  {
  1837          coolkey_private_data_t * priv = COOLKEY_DATA(card);
  1838          int r;
  1839          SC_FUNC_CALLED(card->ctx, SC_LOG_DEBUG_VERBOSE);
  1840
  1841          switch (priv->algorithm) {
  1842          case SC_ALGORITHM_RSA:
  1843                  r = coolkey_rsa_op(card, data, datalen, out, outlen);
  1844                  break;
  1845          case SC_ALGORITHM_EC:
  1846                  r = coolkey_ecc_op(card, data, datalen, out, outlen);
  1847                  break;
  1848          default:
  1849                  r = SC_ERROR_NO_CARD_SUPPORT;
  1850                  break;
  1851          }
  1852
  1853          SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, r);
