  1857  static u8 coolkey_class(unsigned long object_id) {
  1858          return (object_id >> 24) & 0xff;
  1859  }
  1860
  1861  static unsigned short coolkey_get_key_id(unsigned long object_id) {
  1862          char char_index = (object_id >> 16) & 0xff;
  1863          if (char_index >= '0' && char_index <= '9') {
  1864                  return (u8)(char_index - '0');
  1865          }
  1866          if (char_index >= 'A' && char_index <= 'Z') {
  1867                  return (u8)(char_index - 'A' + 10);
  1868          }
  1869          if (char_index >= 'a' && char_index <= 'z') {
  1870                  return (u8)(char_index - 'a' + 26 + 10);
  1871          }
  1872          return COOLKEY_INVALID_KEY;
  1873  }
