  1875  /*
  1876   * COOLKEY cards don't select objects in the applet, objects are selected by a parameter
  1877   * to the APDU. We create paths for the object in which the path value is the object_id
  1878   * and the path type is SC_PATH_SELECT_FILE_ID (so we could cache at the PKCS #15 level if
  1879   * we wanted to.
  1880   *
  1881   * This select simply records what object was selected so that read knows how to access it.
  1882   */
  1883  static int coolkey_select_file(sc_card_t *card, const sc_path_t *in_path, sc_file_t **file_out)
  1884  {
  1885          int r;
  1886          struct sc_file *file = NULL;
  1887          coolkey_private_data_t * priv = COOLKEY_DATA(card);
  1888          unsigned long object_id;
  1889
  1890          assert(card != NULL && in_path != NULL);
  1891
  1892          SC_FUNC_CALLED(card->ctx, SC_LOG_DEBUG_VERBOSE);
  1893
  1894          if (in_path->len != 4) {
  1895                  return SC_ERROR_OBJECT_NOT_FOUND;
  1896          }
  1897          r = coolkey_select_applet(card);
  1898          if (r != SC_SUCCESS) {
  1899                  return r;
  1900          }
  1901          object_id = bebytes2ulong(in_path->value);
  1902          priv->obj = coolkey_find_object_by_id(&priv->objects_list, object_id);
  1903          if (priv->obj == NULL) {
  1904                  return SC_ERROR_OBJECT_NOT_FOUND;
  1905          }
  1906
  1907          priv->key_id = COOLKEY_INVALID_KEY;
  1908          if (coolkey_class(object_id) == COOLKEY_KEY_CLASS) {
  1909                  priv->key_id = coolkey_get_key_id(object_id);
  1910          }
  1911          if (file_out) {
  1912                  file = sc_file_new();
  1913                  if (file == NULL)
  1914                          LOG_FUNC_RETURN(card->ctx, SC_ERROR_OUT_OF_MEMORY);
  1915                  file->path = *in_path;
  1980  coolkey_process_combined_object(sc_card_t *card, coolkey_private_data_t *priv, u8 *object, size_t object_length)
  1981  {
  1982          coolkey_combined_header_t *header = (coolkey_combined_header_t *)object;
  1983          unsigned short compressed_offset;
  1984          unsigned short compressed_length;
  1985          unsigned short compressed_type;
  1986          unsigned short object_offset;
  1987          unsigned short object_count;
  1988          coolkey_decompressed_header_t *decompressed_header;
  1989          u8 *decompressed_object = NULL;
  1990          size_t decompressed_object_len = 0;
  1991          int free_decompressed = 0;
  1992          int i, r;
  1993
  1994          if (object_length < sizeof(coolkey_combined_header_t)) {
  1995                  return SC_ERROR_CORRUPTED_DATA;
  1996          }
  1997          compressed_offset = bebytes2ushort(header->compression_offset);
  1998          compressed_length = bebytes2ushort(header->compression_length);
  1999          compressed_type   = bebytes2ushort(header->compression_type);
  2000
  2001          if ((((size_t)compressed_offset) + (size_t)compressed_length) >  object_length) {
  2002                  return SC_ERROR_CORRUPTED_DATA;
  2003          }
  2004
  2005          /* store the CUID */
  2006          memcpy(&priv->cuid, &header->cuid, sizeof(priv->cuid));
  2007
  2008          if (compressed_type == COOLKEY_COMPRESSION_ZLIB) {
  2009  #ifdef ENABLE_ZLIB
  2010                  r = sc_decompress_alloc(&decompressed_object, &decompressed_object_len, &object[compressed_offset], compressed_length, COMPRESSION_AUTO);
  2011                  if (r)
  2012                          goto done;
  2013                  free_decompressed = 1;
  2014  #else
  2015                  sc_log(card->ctx, "Coolkey compression not supported, no zlib");
  2016                  LOG_FUNC_RETURN(card->ctx, SC_ERROR_NOT_SUPPORTED);
  2017  #endif
  2018          }  else {
  2019                  decompressed_object =&object[compressed_offset];
  2020                  decompressed_object_len = (size_t) compressed_length;
  2021          }
  2022
  2023          decompressed_header = (coolkey_decompressed_header_t *)decompressed_object;
  2024
  2025          if (decompressed_object_len < sizeof(coolkey_decompressed_header_t)) {
  2026                  return SC_ERROR_CORRUPTED_DATA;
  2027          }
  2028          object_offset = bebytes2ushort(decompressed_header->object_offset);
  2029          object_count = bebytes2ushort(decompressed_header->object_count);
  2030
  2031
  2032          /*
  2033           * using 2 different tests here so we can log different errors if logging is
  2034           * turned on.
  2035           */
  2036          /* make sure token_name doesn't overrun the buffer */
  2037          if (decompressed_header->token_name_length +
  2038                  offsetof(coolkey_decompressed_header_t,token_name) > decompressed_object_len) {
  2039                  r = SC_ERROR_CORRUPTED_DATA;
  2040                  goto done;
  2041          }
  2042          /* make sure it doesn't overlap the object space */
  2043          if (decompressed_header->token_name_length +
  2044                  offsetof(coolkey_decompressed_header_t,token_name) > object_offset) {
  2045                  r = SC_ERROR_CORRUPTED_DATA;
  2046                  goto done;
  2047          }
  2048
  2049          /* store the token name in the priv structure so the emulator can set it */
  2050          priv->token_name = malloc(decompressed_header->token_name_length+1);
  2051          if (priv->token_name == NULL) {
  2052                  r = SC_ERROR_OUT_OF_MEMORY;
  2053                  goto done;
  2054          }
  2055          memcpy(priv->token_name, &decompressed_header->token_name[0],
  2056                                                          decompressed_header->token_name_length);
  2057          priv->token_name[decompressed_header->token_name_length] = 0;
  2058          priv->token_name_length = decompressed_header->token_name_length;
  2059
  2060
  2061          for (i=0; i < object_count && object_offset < decompressed_object_len; i++ ) {
  2062                  u8 *current_object = &decompressed_object[object_offset];
  2063                  coolkey_combined_object_header_t *object_header =
  2064                                  (coolkey_combined_object_header_t *)current_object;
  2065                  unsigned long object_id = bebytes2ulong(object_header->object_id);
  2066                  int current_object_len;
  2067
  2068                  /* figure out how big it is */
  2069                  r = coolkey_v1_get_object_length(current_object, decompressed_object_len-object_offset);
  2070                  if (r < 0) {
  2071                          goto done;
  2072                  }
  2073                  if ((size_t)r + object_offset > decompressed_object_len) {
  2074                          r = SC_ERROR_CORRUPTED_DATA;
  2075                          goto done;
  2076                  }
  2077                  current_object_len = r;
  2078                  object_offset += current_object_len;
  2079
  2080                  /* record this object */
  2081                  r = coolkey_add_object(priv, object_id, current_object, current_object_len, 1);
  2082                  if (r) {
  2083                          goto done;
  2084                  }
  2085
  2086          }
  2087          r = SC_SUCCESS;
  2088
  2089  done:
  2090          if (free_decompressed) {
  2091                  free(decompressed_object);
  2092          }
  2093          return r;
  2094  }
