  2107  /*
  2108   * Initialize the Coolkey data structures.
  2109   */
  2110  static int coolkey_initialize(sc_card_t *card)
  2111  {
  2112          int r;
  2113          coolkey_private_data_t *priv = NULL;
  2114          coolkey_life_cycle_t life_cycle;
  2115          coolkey_object_info_t object_info;
  2116          int combined_processed = 0;
  2117
  2118          /* already found? */
  2119          if (card->drv_data) {
  2120                  return SC_SUCCESS;
  2121          }
  2122          sc_debug(card->ctx, SC_LOG_DEBUG_VERBOSE,"Coolkey Applet found");
  2123
  2124          priv = coolkey_new_private_data();
  2125          if (priv == NULL) {
  2126                  r = SC_ERROR_OUT_OF_MEMORY;
  2127                  goto cleanup;
  2128          }
  2129          r = coolkey_get_life_cycle(card, &life_cycle);
  2130          if (r < 0) {
  2131                  goto cleanup;
  2132          }
  2133
  2134          /* Select a coolkey read the coolkey objects out */
  2135          r = coolkey_select_applet(card);
  2136          if (r < 0) {
  2137                  goto cleanup;
  2138          }
  2139
  2140          priv->protocol_version_major = life_cycle.protocol_version_major;
  2141          priv->protocol_version_minor = life_cycle.protocol_version_minor;
  2142          priv->pin_count = life_cycle.pin_count;
  2143          priv->life_cycle = life_cycle.life_cycle;
  2144
  2145          /* walk down the list of objects and read them off the token */
  2146          r = coolkey_list_object(card, COOLKEY_LIST_RESET, &object_info);
  2147          while (r >= 0) {
  2148                  unsigned long object_id;
  2149                  unsigned short object_len;
  2150
  2151                  /* The card did not return what we expected: Lets try other objects */
  2152                  if ((size_t)r < (sizeof(object_info)))
  2153                          break;
  2154
  2155                  /* TODO also look at the ACL... */
  2156
  2157                  object_id = bebytes2ulong(object_info.object_id);
  2158                  object_len = bebytes2ulong(object_info.object_length);
  2159
  2160
  2161                  /* the combined object is a single object that can store the other objects.
  2162                   * most coolkeys provisioned by TPS has a single combined object that is
  2163                   * compressed greatly increasing the effectiveness of compress (since lots
  2164                   * of certs on the token share the same Subject and Issuer DN's). We now
  2165                   * process it separately so that we can have both combined objects managed
  2166                   * by TPS and user managed certs on the same token */
  2167                  if (object_id == COOLKEY_COMBINED_OBJECT_ID) {
  2168                          u8 *object = malloc(object_len);
  2169                          if (object == NULL) {
  2170                                  r = SC_ERROR_OUT_OF_MEMORY;
  2171                                  break;
  2172                          }
  2173                          r = coolkey_read_object(card, COOLKEY_COMBINED_OBJECT_ID, 0, object, object_len,
  2174                                                                                          priv->nonce, sizeof(priv->nonce));
  2175                          if (r < 0) {
  2176                                  free(object);
  2177                                  break;
  2178                          }
  2179                          r = coolkey_process_combined_object(card, priv, object, r);
  2180                          free(object);
  2181                          if (r != SC_SUCCESS) {
  2182                                  break;
  2183                          }
  2184                          combined_processed = 1;
  2185                  } else {
  2186                          r = coolkey_add_object(priv, object_id, NULL, object_len, 0);
  2187                          if (r != SC_SUCCESS)
  2188                                  sc_log(card->ctx, "coolkey_add_object() returned %d", r);
  2189                  }
  2190
  2191                  /* Read next object: error is handled on the cycle condition and below after cycle */
  2192                  r = coolkey_list_object(card, COOLKEY_LIST_NEXT, &object_info);
  2193          }
  2194          if (r != SC_ERROR_FILE_END_REACHED) {
  2195                  /* This means the card does not cooperate at all: bail out */
